#include <iostream>
#include <memory>

class Resource {
public:
  Resource() { std::cout << "Resource acquired\n"; }
  ~Resource() { std::cout << "Resource released\n"; }
};

int main() {
  { // Resource will be released when this scope ends
    std::unique_ptr<Resource> res(new Resource());  //RAII in action using unique_ptr
  }

  //Here, the resource is automatically released thanks to unique_ptr's destructor
  return 0;
}
